INSERT INTO `ref_commentary_templates` (`id`, `event_type`, `template`, `weight`, `interest_score`, `scope`, `template_source`) VALUES
  (1, 'OVERTAKE', '{attacker} is through on {defender} at the final corner -- that is P{pos}.', 0.5000, 55, 'CIRCUIT', 'DOC'),
  (2, 'SAFETY_CAR_DEPLOYED', 'Safety car. Everyone who has not stopped is suddenly in the wrong place.', 0.7000, 70, 'CIRCUIT', 'DOC'),
  (3, 'TYRE_CLIFF', '{driver} has fallen off the cliff -- 1.4 seconds slower than last lap.', 0.7000, 60, 'CIRCUIT', 'DOC'),
  (4, 'WEATHER_CHANGE', 'Rain at turn 7. Only turn 7. For now.', 0.6000, 65, 'BOTH', 'DOC'),
  (5, 'RIVAL_PIT', '{team} have blinked first -- {driver} in from P{pos}.', 0.7000, 50, 'CIRCUIT', 'DOC'),
  (6, 'OVERTAKE', 'Around the outside! {attacker} takes P{pos} from {defender}.', 0.3000, 55, 'CIRCUIT', 'AUTHORED'),
  (7, 'OVERTAKE', '{attacker} finally gets it done on {defender} -- P{pos}.', 0.2000, 50, 'CIRCUIT', 'AUTHORED'),
  (8, 'OVERTAKE_FAILED', '{attacker} has a look at {defender} and thinks better of it.', 0.6000, 25, 'CIRCUIT', 'AUTHORED'),
  (9, 'OVERTAKE_FAILED', '{attacker} runs wide trying it on {defender} -- still P{pos}.', 0.4000, 30, 'CIRCUIT', 'AUTHORED'),
  (10, 'LEAD_CHANGE', 'New leader. {driver} is through into P1.', 0.7000, 85, 'CIRCUIT', 'AUTHORED'),
  (11, 'LEAD_CHANGE', '{driver} takes the lead with {laps_left} laps to run.', 0.3000, 85, 'CIRCUIT', 'AUTHORED'),
  (12, 'RACE_START', 'Lights out. {driver} makes the better start from P{pos}.', 0.5000, 40, 'BOTH', 'AUTHORED'),
  (13, 'RACE_START', 'Clean getaway for the whole field.', 0.5000, 20, 'BOTH', 'AUTHORED'),
  (14, 'FINAL_LAP', 'White flag. One lap between {driver} and P{pos}.', 0.6000, 60, 'CIRCUIT', 'AUTHORED'),
  (15, 'FINAL_LAP', 'Last lap. Nothing left to give but everything left to lose.', 0.4000, 55, 'CIRCUIT', 'AUTHORED'),
  (16, 'CHEQUERED_FLAG', 'Chequered flag. {driver} takes the win.', 0.6000, 90, 'CIRCUIT', 'AUTHORED'),
  (17, 'CHEQUERED_FLAG', 'It''s over. {driver} crosses the line in P{pos}.', 0.4000, 45, 'CIRCUIT', 'AUTHORED'),
  (18, 'RACE_WIN', '{driver} wins it -- the margin is {margin_ms}.', 0.6000, 95, 'BOTH', 'AUTHORED'),
  (19, 'RACE_WIN', '{team} take the win with {driver} at the wheel.', 0.4000, 90, 'BOTH', 'AUTHORED'),
  (20, 'PODIUM', '{driver} is on the podium in P{pos}.', 0.6000, 55, 'BOTH', 'AUTHORED'),
  (21, 'PODIUM', 'A first podium of the year for {team}.', 0.4000, 60, 'BOTH', 'AUTHORED'),
  (22, 'RETIREMENT', '{driver} is out. {car} stopped at the side, and that is a DNF.', 0.6000, 70, 'BOTH', 'AUTHORED'),
  (23, 'RETIREMENT', 'That is the end of {team}''s afternoon -- {driver} retires.', 0.4000, 70, 'BOTH', 'AUTHORED'),
  (24, 'DNS', '{driver} does not take the start. The team will need the reserve.', 0.6000, 50, 'BOTH', 'AUTHORED'),
  (25, 'DNS', '{car} does not leave the garage. A blow before the race has even started.', 0.4000, 45, 'BOTH', 'AUTHORED'),
  (26, 'YELLOW_FLAG', 'Yellow flag at {corner}. Hands off the wheel through there.', 0.6000, 30, 'CIRCUIT', 'AUTHORED'),
  (27, 'YELLOW_FLAG', 'Local yellow through {corner} -- something for the marshals to clear.', 0.4000, 25, 'CIRCUIT', 'AUTHORED'),
  (28, 'SAFETY_CAR_DEPLOYED', 'The pace car is out. {team} will already be doing the sums on when to stop.', 0.3000, 65, 'CIRCUIT', 'AUTHORED'),
  (29, 'SAFETY_CAR_ENDING', 'Green flag. Racing resumes.', 0.6000, 55, 'CIRCUIT', 'AUTHORED'),
